const disclosure = '';
function sectionHead(kicker,title,copy=''){return `<div class="section-heading"><span class="eyebrow">${kicker}</span><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>`;}
function ctaBand(title='Experience Ranawat Courtyard.',text='Plan a celebration, enquire about a stay, or visit the boutique. Our team will be glad to welcome you.'){return `<section class="cta-band"><div><span class="eyebrow">Your visit awaits</span><h2>${title}</h2><p>${text}</p></div><div class="cta-actions"><a class="button button-ivory" href="/contact">Enquire now <span>↗</span></a><a class="button button-outline" href="${wa('Hello Ranawat Courtyard, I would like to know more.')}" target="_blank" rel="noreferrer">WhatsApp <span>↗</span></a></div></section>`;}
function picture(src,alt,ratio='landscape'){return `<figure class="photo ${ratio}">${image(src,alt)}${disclosure}</figure>`;}
function storyBlock({kicker,title,text,image:src,alt,href,label,reverse=false}){return `<section class="story-block text-story ${reverse?'reverse':''}"><div class="story-copy"><span class="eyebrow">${kicker}</span><h2>${title}</h2><p>${text}</p>${href?link(label,href):''}</div><figure class="story-aside">${image(src,alt)}<figcaption>${kicker}</figcaption></figure></section>`;}
function experienceCard(item,index){return `<a class="experience-card" href="${item.href}"><div class="experience-image">${image(item.image,item.title)}<span class="experience-number">0${index+1}</span></div><div class="experience-copy"><div><span class="eyebrow">Ranawat experience</span><h3>${item.title}</h3><p>${item.text}</p></div><span class="round-arrow" aria-hidden="true">↗</span></div></a>`;}
function parallaxHeroTiles(){return `<div class="parallax-hero-images" data-parallax-hero aria-hidden="true">${parallaxPhotos.map((src,i)=>`<div class="parallax-tile parallax-${['top-left','top-right','mid-left','mid-right','bottom-left','bottom-right','far-left','far-right'][i]}" data-parallax-tile data-depth="${[.3,.35,.9,.85,.4,.45,.25,.2][i]}" style="--tile-index:${i};--float-duration:${6.8+i*.42}s;--float-delay:${-i*.72}s;--float-depth:${16+(i%3)*5}px;--float-y:-${7+(i%3)*2}px;--float-tilt:${i%2?'-2.4deg':'2.4deg'}">${image(src,'','', 'eager')}</div>`).join('')}</div>`;}
function stackCard(item,index){return `<article class="stack-card" data-stack-card="${index}" style="--card-index:${index};z-index:${index+1}"><div class="stack-card-frame">${image(item.image,`${item.title} · representative image`)}<canvas class="canvas-reveal" data-canvas-reveal aria-hidden="true"></canvas><div class="stack-card-shade"></div><div class="stack-card-copy"><span class="eyebrow">0${index+1} · Ranawat experience</span><h3>${item.title}</h3><p>${item.text}</p><a href="${item.href}" data-cursor="EXPLORE" aria-label="${item.link}">${item.link}<span aria-hidden="true"> ↗</span></a></div><span class="image-note">Representative image</span></div></article>`;}
function hero(title,subtitle,src=assets.hero,crumb='Chhatarpur · Madhya Pradesh',compact=false){return `<section class="page-hero editorial-page-hero ${compact?'compact':''}"><div class="page-hero-image" aria-hidden="true">${image(src,'','', 'eager')}</div><div class="hero-shade" aria-hidden="true"></div><div class="page-hero-copy"><span class="eyebrow">${crumb} · Ranawat Courtyard</span><h1>${title}</h1><p>${subtitle}</p></div></section>`;}
function collectionCards(){return collections.map((c,i)=>`<a class="collection-card" href="#catalogue" data-collection="${c.id}"><div class="collection-photo">${image(c.image,c.name)}<span>0${i+1}</span></div><div class="collection-info"><h3>${c.name}</h3><p>${c.desc}</p><small>${c.styles.slice(0,4).join(' · ')}</small></div></a>`).join('');}
function productCard(p){const cat=collections.find(c=>c.id===p.category);return `<article class="product-card" data-3d-card><button class="product-image" type="button" data-card-depth="38" data-product="${p.id}" data-cursor="VIEW" aria-label="View ${esc(p.name)}">${image(p.image,p.name)}<span>View piece ↗</span></button><div class="product-info"><small data-card-depth="24">${esc(cat?.short||'Collection')}</small><h3 data-card-depth="32">${esc(p.name)}</h3><p data-card-depth="18">${esc(p.summary)}</p><button class="quiet-button" data-cursor="ENQUIRE" data-card-depth="28" type="button" data-product="${p.id}">Enquire for availability <span>↗</span></button></div></article>`;}
function pageHome(){return `<section class="home-hero editorial-home-hero cinematic-home-hero"><div class="home-hero-photo" aria-hidden="true"><video muted playsinline preload="auto" poster="/media/ranawat-hero-final.jpg"><source src="/media/ranawat-hero-cinematic.mp4" type="video/mp4"></video></div><div class="hero-shade" aria-hidden="true"></div><div class="home-hero-copy"><span class="eyebrow">Nowgong Road · Chhatarpur, Madhya Pradesh</span><div class="hero-type-stage"><h1><span class="hero-title-main">Ranawat</span><span class="hero-title-sub">Courtyard</span></h1></div><p class="hero-tagline">A place to gather,<br>stay and discover.</p><p class="hero-description">Weddings and celebrations, a private farmhouse stay, Indian textiles, dining and hospitality in Chhatarpur.</p><div class="hero-actions"><a class="button button-primary" data-cursor="EXPLORE" href="/architecture-gardens">Explore Ranawat <span>↗</span></a><a class="button button-outline-light" data-cursor="ENQUIRE" href="/contact?type=stay">Enquire about a stay <span>↗</span></a></div></div><aside class="hero-folio"><span class="eyebrow">The address</span><b>Nowgong Road</b><span>Chhatarpur<br>Madhya Pradesh</span><i></i><small>GATHER · STAY · DISCOVER</small></aside><div class="hero-scroll"><i></i><span>Discover</span></div></section>
<main class="home-page"><section class="intro-section"><div class="intro-copy"><span class="eyebrow">A welcome to Ranawat Courtyard</span><h2>More Than a Destination.<br><em>An Experience.</em></h2><p>On Nowgong Road in Chhatarpur, architecture, gardens, celebrations, accommodation, traditional fashion and hospitality come together in one distinctive setting.</p>${link('Our story','/about')}</div><div class="intro-photo" data-chromatic-image>${image(assets.entrance,'Courtyard entrance at Ranawat')}<span>01 — A place to gather</span></div></section>
<div class="home-marquee" aria-label="Heritage · gardens · celebrations · stays · Indian traditions · hospitality"><div class="marquee-track"><div class="marquee-group"><span>Heritage</span><i></i><span>Gardens</span><i></i><span>Celebrations</span><i></i><span>Private stays</span><i></i><span>Indian traditions</span><i></i><span>Hospitality</span><i></i></div><div class="marquee-group" aria-hidden="true"><span>Heritage</span><i></i><span>Gardens</span><i></i><span>Celebrations</span><i></i><span>Private stays</span><i></i><span>Indian traditions</span><i></i><span>Hospitality</span><i></i></div></div></div>
<section class="home-experiences page-gutter">${sectionHead('Six experiences · one address','The courtyard, at your own pace.','Explore the places and occasions associated with Ranawat Courtyard. Confirm details with the team.') }<div class="home-experience-list">${experiences.map((item,i)=>`<a href="${item.href}" class="home-experience-row"><span>0${i+1}</span><h3>${item.title}</h3><p>${item.text}</p><b aria-hidden="true">↗</b></a>`).join('')}</div></section>
${storyBlock({kicker:'Architecture & gardens',title:'A setting shaped by light, pattern and place.',text:'Ask the Ranawat team about the property, its grounds and current arrangements for a visit.',image:assets.arches,alt:'Arched corridor at Ranawat Courtyard',href:'/architecture-gardens',label:'Explore the architecture'})}
<section class="home-feature page-gutter"><div class="home-feature-copy"><span class="eyebrow">Celebrations at Ranawat</span><h2>Gather beautifully.<br><em>Celebrate together.</em></h2><p>From wedding ceremonies and receptions to haldi, mehendi and family milestones, discover indoor and outdoor spaces for your celebration.</p>${link('Plan your celebration','/weddings-events')}</div><aside class="home-feature-note">${image(assets.wedding,'Outdoor wedding lawn at Ranawat Courtyard')}<span>01 — Gather</span><b>Weddings<br>& celebrations</b></aside></section>
<section class="boutique-feature"><div class="boutique-feature-image">${image(assets.sarees,'Traditional Indian textiles at the Ranawat boutique')}</div><div class="boutique-feature-copy"><span class="eyebrow">The Ranawat cultural boutique</span><h2>Celebrating the Timeless Beauty of Indian Traditions.</h2><p>Explore a considered edit of regional weaves, festive silhouettes, jewellery and accessories. Enquiry-led catalogue; current availability is confirmed by the team.</p>${link('Discover the collections','/boutique')}</div></section>
<section class="home-gallery-note page-gutter"><div><span class="eyebrow">A visual record</span><h2>Ranawat, in its own light.</h2></div><p>Browse photographs of the courtyard, gardens, celebrations, farmhouse and boutique.</p>${link('View the gallery','/gallery')}</section>${ctaBand()}</main>`;}
function pageAbout(){return `${hero('A destination where heritage feels at home.','Ranawat Courtyard brings together architecture, gardens, celebrations, stays and Indian cultural traditions on Nowgong Road, Chhatarpur.',assets.entrance,'Our story')}<main><section class="philosophy page-gutter">${sectionHead('Our philosophy','Where Heritage Meets<br><em>Timeless Elegance.</em>','Ranawat Courtyard was imagined as more than a venue. It is a place to celebrate, to stay, to shop and to share a meal — the details of its spaces, grounds and arrangements confirmed directly with the team.') }<div class="philosophy-quote">“Heritage in every detail.<br>Elegance in every experience.”</div></section>${storyBlock({kicker:'Six experiences, one courtyard',title:'A thoughtful welcome for every occasion.',text:'From time spent among the gardens to a wedding day shared with family, a restful farmhouse stay or a visit to our traditional boutique, each experience is shaped by the same spirit of warmth.',image:assets.garden,alt:'Gardens at Ranawat Courtyard',href:'/architecture-gardens',label:'Discover the property',reverse:true})}<section class="values-section page-gutter">${sectionHead('The Ranawat experience','Distinct moments, thoughtfully brought together.') }<div class="value-grid">${[['01','Heritage','Ask the team for current details about the property, its spaces and grounds.'],['02','Nature','An outdoor lawn is listed for events; ask the team about current access and arrangements.'],['03','Celebration','Indoor and outdoor settings for weddings, rituals and family milestones.'],['04','Culture','A boutique celebrating Indian textiles, traditional wear and craft.'],['05','Comfort','A private two-bedroom farmhouse for families and guests.'],['06','Hospitality','Food and care offered in the spirit of a traditional Indian welcome.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="address-strip page-gutter"><span class="eyebrow">Find us</span><p>${address}</p>${link('Get directions',maps)}</section>${ctaBand()}</main>`;}
function pageArchitecture(){return `${hero('Architecture & Gardens','Explore the architecture, grounds and visiting arrangements at Ranawat Courtyard.',assets.arches,'Spaces & setting')}<main><section class="architecture-intro page-gutter">${sectionHead('A sense of place','Details shaped by light and pattern.','View the courtyard, entrance and grounds, then contact the Ranawat team for current information about spaces and visiting arrangements.') }<div class="architecture-pair">${picture(assets.entrance,'The entrance at Ranawat Courtyard')}${picture(assets.arches,'Arched corridor at Ranawat Courtyard','portrait')}</div></section>${storyBlock({kicker:'Indoor event space',title:'A place for indoor gatherings.',text:'An indoor event space is listed for ceremonies, receptions and family gatherings. Ask the team to confirm current layouts and arrangements.',image:assets.banquet,alt:'Indoor banquet space at Ranawat Courtyard'})}${storyBlock({kicker:'Outdoor grounds',title:'Space for outdoor occasions.',text:'The venue lists an outdoor lawn for events. Contact the team to confirm layout, access and availability.',image:assets.garden,alt:'Lawn and gardens at Ranawat Courtyard',reverse:true})}<section class="detail-ribbon page-gutter"><span>Indoor event space</span><i></i><span>Outdoor lawn</span><i></i><span>Farmhouse stay</span><i></i><span>Chhatarpur</span></section>${ctaBand('Ask about the property.','Contact the team for current details about the spaces and visit arrangements.')}</main>`;}
function enquiryForm(kind='wedding'){const title=kind==='stay'?'Stay enquiry':kind==='wedding'?'Wedding & event enquiry':kind==='boutique'?'Boutique enquiry':'Send an enquiry';return `<form class="enquiry-form" data-form="${kind}" novalidate><div class="form-heading"><span class="eyebrow">${title}</span><p>Share a few details and we’ll prepare a WhatsApp enquiry for you. Sending an enquiry does not confirm a booking.</p></div><div class="form-grid"><label>Full name<input name="name" required autocomplete="name" placeholder="Your name"></label><label>Phone<input name="phone" required type="tel" inputmode="tel" autocomplete="tel" pattern="[+0-9() -]{8,18}" placeholder="Your phone number"></label><label>Email <span class="optional">Optional</span><input name="email" type="email" autocomplete="email" placeholder="you@example.com"></label>${kind==='wedding'?`<label>Event type<select name="eventType" required><option value="">Select event</option>${experiencesEvents.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Event date<input name="date" type="date"></label><label>Expected guests<input name="guests" type="number" min="1" max="10000" placeholder="Guest count"></label><label>Space preference<select name="space"><option value="">Select preference</option><option>Indoor banquet</option><option>Outdoor lawn</option><option>Open to both</option></select></label>`:''}${kind==='stay'?`<label>Number of guests<input name="guests" type="number" min="1" max="8" required placeholder="Guests"></label><label>Check-in<input name="checkin" type="date" required></label><label>Check-out<input name="checkout" type="date" required></label>`:''}${kind==='boutique'?`<label>Collection<select name="collection"><option value="">Select collection</option>${collections.map(c=>`<option>${c.name}</option>`).join('')}</select></label>`:''}<label class="full">${kind==='boutique'?'Item or style of interest':'Additional requirements'}<textarea name="notes" rows="3" placeholder="Tell us a little more..."></textarea></label></div><div class="form-bottom"><button class="button button-primary" type="submit">Continue on WhatsApp <span>↗</span></button><span class="form-status" role="status" aria-live="polite"></span><small>We’ll open WhatsApp with your details ready to send.</small></div></form>`;}
function pageWedding(){return `${hero('Weddings & Celebrations','A beautiful setting for the moments your family will remember.',assets.wedding,'Gather at Ranawat')}<main><section class="event-intro page-gutter">${sectionHead('Celebrations at Ranawat','A day that feels like your own.','From the first ceremony to the last dance, bring your family together for weddings, receptions, engagements and cherished milestones.') }<div class="occasion-list">${experiencesEvents.map((x,i)=>`<span><b>0${i+1}</b>${x}</span>`).join('')}</div></section>${storyBlock({kicker:'Indoor banquet',title:'An intimate gathering, beautifully set.',text:'An indoor event space is listed for ceremonies, receptions and family gatherings. Ask the team to confirm current layouts and arrangements.',image:assets.banquet,alt:'Indoor banquet at Ranawat Courtyard'})}${storyBlock({kicker:'Outdoor lawn',title:'Celebrate beneath the open sky.',text:'An outdoor lawn is listed as an event area. Ask about ceremony layouts, décor, capacity and availability.',image:assets.wedding,alt:'Outdoor wedding lawn at Ranawat Courtyard',reverse:true})}<section class="form-section page-gutter" id="enquiry">${enquiryForm('wedding')}</section>${ctaBand('Begin planning your celebration.','Tell us about your occasion and our team will connect with you.')}</main>`;}
function pageStay(){return `${hero('A private farmhouse stay','A restful place to settle in, spend time together and feel at home.',assets.bedroom,'Stay at Ranawat')}<main><section class="stay-intro page-gutter">${sectionHead('Farmhouse stay','Space to unwind together.','A private two-bedroom farmhouse with king-size beds and a living area, positioned for up to eight guests. Please ask our team to confirm dates, facilities and current arrangements.') }<div class="stay-facts"><div><b>02</b><span>Bedrooms</span></div><div><b>08</b><span>Guests · listed capacity</span></div><div><b>01</b><span>Living area</span></div></div></section>${storyBlock({kicker:'Rest & recharge',title:'A calm retreat between celebrations.',text:'Enjoy a private stay with room to gather and unwind. Ask the team about the rooms, views, facilities and dates that suit your visit.',image:assets.bedroom,alt:'Farmhouse bedroom at Ranawat Courtyard'})}${storyBlock({kicker:'Time together',title:'A living space to make your own.',text:'The listed farmhouse includes a living area. Contact the team to confirm current facilities and arrangements.',image:assets.living,alt:'Farmhouse living area at Ranawat Courtyard',reverse:true})}<section class="form-section page-gutter" id="enquiry">${enquiryForm('stay')}</section>${ctaBand('Plan a restful stay.','Enquire about your dates and guest requirements.')}</main>`;}
function pageBoutique(){return `${hero('The Cultural Boutique','Celebrating the Timeless Beauty of Indian Traditions.',assets.poshak,'The Ranawat edit')}<main><section class="boutique-intro page-gutter">${sectionHead('A considered edit','Textiles and traditions, beautifully expressed.','Discover festive silhouettes, regional weaves, ethnic suits, jewellery and gifts. This enquiry-led catalogue is illustrative; items, specifications and availability require confirmation.') }<div class="boutique-categories">${collectionCards()}</div></section><section class="catalogue-section page-gutter" id="catalogue">${sectionHead('The catalogue','A closer look at the collection.','Browse sample pieces and ask us about current availability and price.') }<div class="catalogue-toolbar"><div class="filter-list" role="group" aria-label="Filter products by collection"><button class="filter active" data-product-filter="all">All pieces <span>18</span></button>${collections.map(c=>`<button class="filter" data-product-filter="${c.id}">${c.short}</button>`).join('')}</div><p>Illustrative catalogue · enquire to confirm availability</p></div><div class="product-grid" id="product-grid"></div><p class="stock-note">Catalogue images and listings are illustrative. Stock, fabric, specifications, current availability and pricing are confirmed by the Ranawat Courtyard team when you enquire. No online checkout or payment is offered.</p></section>${ctaBand('Find your piece.','Enquire with our boutique team about a collection or item.')}</main>`;}
