let pageEffectCleanups=[];
let productCardCleanup=()=>{};
function header(path){return `<div class="topline"><span>Nowgong Road · Chhatarpur, Madhya Pradesh</span><a href="tel:${phone}">Call +91 93992 57285</a></div><header class="site-header ${path==='/'?'site-header-home':''}"><a class="wordmark" href="/" aria-label="Ranawat Courtyard home"><b>Ranawat</b><small>Courtyard</small></a><nav class="desktop-nav" aria-label="Main navigation">${nav.map(([name,href])=>`<a href="${href}" data-cursor="EXPLORE" ${path===href?'aria-current="page"':''}>${name}</a>`).join('')}</nav><a class="header-cta" data-cursor="ENQUIRE" href="/contact">Enquire <span>↗</span></a><button class="menu-toggle" type="button" aria-label="Open navigation" aria-expanded="false"><span></span><span></span></button></header><nav class="mobile-nav" aria-label="Mobile navigation" hidden>${[['Home','/'],...nav].map(([name,href])=>`<a href="${href}" ${path===href?'aria-current="page"':''}>${name}<span>↗</span></a>`).join('')}<a class="mobile-phone" href="tel:${phone}">+91 93992 57285</a></nav>`;}
function footer(){return `<footer class="site-footer"><div class="footer-brand"><a class="wordmark dark" href="/"><b>Ranawat</b><small>Courtyard</small></a><div class="ornament"><i></i><i></i></div><p>Heritage in every detail.<br>Elegance in every experience.</p></div><div class="footer-grid"><div><span class="eyebrow">Visit</span><a href="${maps}" target="_blank" rel="noreferrer">${address}<br><small>Open directions ↗</small></a></div><div><span class="eyebrow">Connect</span><a href="tel:${phone}">+91 93992 57285</a><a href="https://www.instagram.com/ranawat_courtyard/" target="_blank" rel="noreferrer">@ranawat_courtyard ↗</a><a href="${wa('Hello Ranawat Courtyard, I would like to make an enquiry.')}" target="_blank" rel="noreferrer">WhatsApp ↗</a></div><div><span class="eyebrow">Explore</span><div class="footer-links">${[['Home','/'],...nav].map(([n,h])=>`<a href="${h}">${n}</a>`).join('')}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Ranawat Courtyard, Chhatarpur.</span><span>Explore photo stories from Ranawat Courtyard.</span><a href="https://share.google/za5UEyBcEl78ztul3" target="_blank" rel="noreferrer">Google Business ↗</a></div></footer><div class="floating-actions"><a href="tel:${phone}" aria-label="Call Ranawat Courtyard">${callIcon}</a><a href="${wa('Hello Ranawat Courtyard, I have an enquiry.')}" target="_blank" rel="noreferrer" aria-label="WhatsApp Ranawat Courtyard">${messageIcon}</a></div>`;}

function render(){
  pageEffectCleanups.forEach(cleanup=>cleanup());pageEffectCleanups=[];productCardCleanup();productCardCleanup=()=>{};
  const path=current();const page=pages[path]||pages['/'];
  document.title=page.title;
  const desc=$('meta[name="description"]'); if(desc)desc.content=page.desc;
  const ogTitle=$('meta[property="og:title"]');if(ogTitle)ogTitle.content=page.title;
  const ogDesc=$('meta[property="og:description"]');if(ogDesc)ogDesc.content=page.desc;
  const twTitle=$('meta[name="twitter:title"]');if(twTitle)twTitle.content=page.title;
  const twDesc=$('meta[name="twitter:description"]');if(twDesc)twDesc.content=page.desc;
  const canonical=$('link[rel="canonical"]');if(canonical)canonical.href=new URL(path==='/'?'/':path,location.origin).href;
  $('#app').innerHTML=header(path)+page.render()+footer();
  initPage(path);window.scrollTo(0,0);
}
function initPage(path){
  const toggle=$('.menu-toggle'),mobile=$('.mobile-nav');toggle?.addEventListener('click',()=>{const opened=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!opened));toggle.setAttribute('aria-label',opened?'Open navigation':'Close navigation');mobile.hidden=opened;document.body.classList.toggle('menu-open',!opened);});
  mobile?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobile.hidden=true;document.body.classList.remove('menu-open');}));
  if(path==='/boutique'){renderProducts('all');$('.catalogue-section')?.addEventListener('click',e=>{const f=e.target.closest('[data-product-filter]');if(f){$('.filter.active', $('.catalogue-toolbar')).classList.remove('active');f.classList.add('active');renderProducts(f.dataset.productFilter);}const p=e.target.closest('[data-product]');if(p)openProduct(p.dataset.product);});document.querySelectorAll('.collection-card').forEach(a=>a.addEventListener('click',()=>{const f=$(`[data-product-filter="${a.dataset.collection}"]`);$('.catalogue-toolbar .filter.active')?.classList.remove('active');f?.classList.add('active');renderProducts(a.dataset.collection);setTimeout(()=>$('#catalogue')?.scrollIntoView({behavior:'smooth'}),0);}));}
  if(path==='/gallery'){renderGallery('All');$('.gallery-toolbar')?.addEventListener('click',e=>{const f=e.target.closest('[data-gallery-filter]');if(!f)return;$('.gallery-toolbar .filter.active').classList.remove('active');f.classList.add('active');renderGallery(f.dataset.galleryFilter);});$('#gallery-grid')?.addEventListener('click',e=>{const item=e.target.closest('[data-gallery]');if(item)openGallery(Number(item.dataset.gallery));});}
  document.querySelectorAll('[data-gallery]:not(#gallery-grid [data-gallery])').forEach(el=>el.addEventListener('click',()=>openGallery(Number(el.dataset.gallery))));
  document.querySelectorAll('form[data-form]').forEach(form=>{if(form.dataset.form==='contact')initContactForm(form);form.addEventListener('submit',submitForm);});
  initPageMotion();
  if(location.hash){requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView({behavior:'smooth'}));}
}
function initPageMotion(){
  const hero=$('.home-hero');
  if(hero){
    const photo=$('.home-hero-photo',hero),video=$('video',photo),indicator=$('.hero-scroll',hero),title3d=$('.hero-type-stage h1',hero);let scrollFrame=0;
    if(video){
      hero.classList.add('has-cinematic-video');
      const showPoster=()=>hero.classList.add('is-video-fallback');
      const onVisibility=entries=>{for(const entry of entries){if(entry.isIntersecting){if(matchMedia('(prefers-reduced-motion: reduce)').matches){hero.classList.add('motion-reduced');video.pause();continue;}hero.classList.remove('is-video-fallback','motion-reduced');if(video.ended||video.currentTime>0)video.currentTime=0;const attempt=video.play();if(attempt?.catch)attempt.catch(showPoster);}else{video.pause();if(video.readyState>0)video.currentTime=0;}}};
      const failed=()=>showPoster();
      const observer=new IntersectionObserver(onVisibility,{threshold:.4});
      video.addEventListener('error',failed);observer.observe(hero);
      pageEffectCleanups.push(()=>{observer.disconnect();video.removeEventListener('error',failed);video.pause();});
    }
    const paintScroll=()=>{scrollFrame=0;const range=Math.max(1,hero.offsetHeight);const progress=Math.min(1,Math.max(0,(window.scrollY-hero.offsetTop)/range));if(video)video.style.transform=`translate3d(0,${(-progress*8).toFixed(1)}px,0) scale(${(1+progress*.06).toFixed(4)})`;if(indicator)indicator.style.opacity=String(1-progress*.8);};
    const requestPaint=()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(paintScroll);};
    window.addEventListener('scroll',requestPaint,{passive:true});window.addEventListener('resize',requestPaint,{passive:true});requestPaint();
    pageEffectCleanups.push(()=>{window.removeEventListener('scroll',requestPaint);window.removeEventListener('resize',requestPaint);cancelAnimationFrame(scrollFrame);});

    if(matchMedia('(pointer:fine)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
      const follower=document.createElement('span');follower.className='cursor-follower';follower.setAttribute('aria-hidden','true');follower.innerHTML='<i></i><span></span>';document.body.classList.add('has-custom-cursor');document.body.append(follower);
      let x=innerWidth/2,y=innerHeight/2,tx=x,ty=y,cursorFrame=0;
      const drawCursor=()=>{x+=(tx-x)*.22;y+=(ty-y)*.22;follower.style.left=`${x.toFixed(1)}px`;follower.style.top=`${y.toFixed(1)}px`;const bounds=hero.getBoundingClientRect(),inside=x>=bounds.left&&x<=bounds.right&&y>=bounds.top&&y<=bounds.bottom,px=(x-bounds.left)/bounds.width-.5,py=(y-bounds.top)/bounds.height-.5;if(video)video.style.translate=inside?`${(-px*5).toFixed(1)}px ${(-py*4).toFixed(1)}px`:'0 0';if(title3d)title3d.style.transform=inside?`perspective(1200px) rotateX(${(-py*3.5).toFixed(2)}deg) rotateY(${(px*5).toFixed(2)}deg) translateZ(12px)`:'';if(Math.abs(tx-x)+Math.abs(ty-y)>.3)cursorFrame=requestAnimationFrame(drawCursor);else cursorFrame=0;};
      const move=e=>{if(e.pointerType==='touch')return;tx=e.clientX;ty=e.clientY;follower.classList.add('is-visible');if(!cursorFrame)cursorFrame=requestAnimationFrame(drawCursor);follower.classList.toggle('is-hero',hero.contains(e.target));};
      const over=e=>{const target=e.target.closest?.('[data-cursor]');const label=target?.dataset.cursor||'';follower.dataset.label=label;follower.classList.toggle('has-label',Boolean(label));follower.classList.toggle('is-cta',Boolean(target?.matches('.button,.header-cta')));};
      const out=e=>{if(!e.relatedTarget){follower.classList.remove('is-visible','is-hero','has-label','is-cta');follower.dataset.label='';}};
      document.addEventListener('pointermove',move,{passive:true});document.addEventListener('pointerover',over,{passive:true});document.addEventListener('pointerout',out,{passive:true});
      const magnetic=[];hero.querySelectorAll('.hero-actions .button').forEach(button=>{const moveButton=e=>{const r=button.getBoundingClientRect();button.style.translate=`${((e.clientX-r.left)/r.width-.5)*8}px ${((e.clientY-r.top)/r.height-.5)*7}px`;};const resetButton=()=>{button.style.translate='0 0';};button.addEventListener('pointermove',moveButton,{passive:true});button.addEventListener('pointerleave',resetButton,{passive:true});magnetic.push(()=>{button.removeEventListener('pointermove',moveButton);button.removeEventListener('pointerleave',resetButton);resetButton();});});
      pageEffectCleanups.push(()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerover',over);document.removeEventListener('pointerout',out);cancelAnimationFrame(cursorFrame);magnetic.forEach(cleanup=>cleanup());follower.remove();document.body.classList.remove('has-custom-cursor');});
    }
  }

  const targets=[...document.querySelectorAll('#app .page-hero-copy, #app main > section:not(.home-hero):not(.scroll-stack-section)')];
  if(!targets.length)return;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  targets.forEach((el,index)=>{el.classList.add('scroll-reveal');el.style.setProperty('--reveal-delay',`${Math.min(index%4,3)*85}ms`);});
  if(!('IntersectionObserver' in window)){targets.forEach(el=>el.classList.add('is-visible'));return;}
  const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}}),{threshold:.08,rootMargin:'0px 0px -24px 0px'});
  targets.forEach(el=>observer.observe(el));
  pageEffectCleanups.push(()=>observer.disconnect());
  if(!reduced)updateScrollStack();
}
function updateScrollStack(){
  const section=$('[data-scroll-stack]');if(!section)return;
  const cards=[...section.querySelectorAll('[data-stack-card]')];if(!cards.length)return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches){cards.forEach(card=>card.style.transform='none');return;}
  const top=section.getBoundingClientRect().top+window.scrollY;
  const travel=Math.max(1,section.offsetHeight-window.innerHeight);
  const progress=Math.min(1,Math.max(0,(window.scrollY-top+window.innerHeight*.18)/travel));
  const lastStart=.78;
  cards.forEach((card,index)=>{const target=Math.max(.5,1-(cards.length-index-1)*.1);const start=index/(cards.length-1)*lastStart;const t=Math.min(1,Math.max(0,(progress-start)/(1-start)));const scale=1+(target-1)*t;card.style.transform=`scale(${scale.toFixed(3)})`;});
}
window.addEventListener('scroll',updateScrollStack,{passive:true});
window.addEventListener('resize',updateScrollStack);
function renderProducts(filter){const grid=$('#product-grid');if(!grid)return;productCardCleanup();const visible=filter==='all'?productNames:productNames.filter(p=>p.category===filter);grid.innerHTML=visible.map(productCard).join('');productCardCleanup=mountThreeDCards(grid);}
function renderGallery(filter){const grid=$('#gallery-grid');if(!grid)return;const items=galleryItems.map((x,i)=>({...x,i})).filter(x=>filter==='All'||x.category===filter);grid.innerHTML=items.map(x=>`<button class="masonry-item" data-gallery="${x.i}" data-cursor="VIEW" aria-label="View ${esc(x.caption)}, ${x.category}">${image(x.image,`${x.caption} at Ranawat Courtyard`)}<span class="masonry-caption"><small>${x.category}</small><b>${x.caption}</b></span></button>`).join('');}
function openProduct(id){const p=productNames.find(x=>x.id===id);if(!p)return;const c=collections.find(x=>x.id===p.category);showModal(`<div class="product-modal"><div class="modal-image">${image(p.image,p.name,'','eager')}<span class="image-note">Illustrative catalogue image</span></div><div class="modal-copy"><button class="modal-close" aria-label="Close">×</button><span class="eyebrow">${c.name} · Sample catalogue piece</span><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><dl><div><dt>Collection</dt><dd>${c.name}</dd></div><div><dt>Availability</dt><dd>Enquire with the boutique team</dd></div><div><dt>Price</dt><dd>On request</dd></div></dl><p class="stock-note">Illustrative listing only. Stock, item details and price are confirmed by the Ranawat Courtyard team.</p><a class="button button-primary" target="_blank" rel="noreferrer" href="${wa(`Hello Ranawat Courtyard, I would like to enquire about “${p.name}” from the ${c.name}. Could you share current availability and price?`)}">Enquire on WhatsApp <span>↗</span></a></div></div>`);}
let galleryIndex=0;
function openGallery(index){galleryIndex=(index+galleryItems.length)%galleryItems.length;const x=galleryItems[galleryIndex];showModal(`<div class="lightbox"><button class="modal-close" aria-label="Close">×</button><button class="lightbox-arrow prev" aria-label="Previous image">←</button>${image(x.image,`${x.caption} at Ranawat Courtyard`,'lightbox-image','eager')}<button class="lightbox-arrow next" aria-label="Next image">→</button><div class="lightbox-caption"><span class="eyebrow">${x.category} · ${galleryIndex+1} / ${galleryItems.length}</span><h2>${x.caption}</h2></div></div>`);$('.lightbox .prev')?.addEventListener('click',()=>openGallery(galleryIndex-1));$('.lightbox .next')?.addEventListener('click',()=>openGallery(galleryIndex+1));let touchX=0;const lb=$('.lightbox');lb?.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;},{passive:true});lb?.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>55)openGallery(galleryIndex+(dx<0?1:-1));},{passive:true});}
function showModal(html){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop" role="presentation"><div class="modal-panel" role="dialog" aria-modal="true">${html}</div></div>`;document.body.classList.add('modal-open');const close=()=>{root.innerHTML='';document.body.classList.remove('modal-open');document.removeEventListener('keydown',keyHandler);};const keyHandler=e=>{if(e.key==='Escape')close();if(e.key==='ArrowLeft'&&$('.lightbox'))openGallery(galleryIndex-1);if(e.key==='ArrowRight'&&$('.lightbox'))openGallery(galleryIndex+1);};document.addEventListener('keydown',keyHandler);$('.modal-close',root)?.addEventListener('click',close);$('.modal-backdrop',root)?.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))close();});$('.modal-close',root)?.focus();}
function initContactForm(form){const type=$('#contact-type'),target=$('#dynamic-fields');const requested=new URLSearchParams(location.search).get('type');if(['wedding','stay','boutique'].includes(requested))type.value=requested;const update=()=>{const v=type.value;if(v==='wedding')target.innerHTML=`<div class="form-grid"><label>Event type<select name="eventType"><option value="">Select event</option>${experiencesEvents.map(e=>`<option>${e}</option>`).join('')}</select></label><label>Event date<input name="date" type="date"></label><label>Expected guests<input name="guests" type="number" min="1" max="10000"></label><label>Space preference<select name="space"><option value="">Select preference</option><option>Indoor banquet</option><option>Outdoor lawn</option><option>Open to both</option></select></label></div>`;else if(v==='stay')target.innerHTML='<div class="form-grid"><label>Number of guests<input name="guests" type="number" min="1" max="8" required></label><label>Check-in<input name="checkin" type="date" required></label><label>Check-out<input name="checkout" type="date" required></label></div>';else if(v==='boutique')target.innerHTML=`<div class="form-grid"><label>Collection<select name="collection"><option value="">Select collection</option>${collections.map(c=>`<option>${c.name}</option>`).join('')}</select></label><label>Item or style<input name="item" placeholder="What are you looking for?"></label></div>`;else target.innerHTML='';};type.addEventListener('change',update);update();}
function submitForm(e){e.preventDefault();const form=e.currentTarget,status=$('.form-status',form);if(!form.reportValidity()){status.textContent='Please check the highlighted fields.';return;}const data=new FormData(form);const f=Object.fromEntries(data.entries());if((form.dataset.form==='stay'||f.type==='stay')&&f.checkin&&f.checkout&&f.checkout<=f.checkin){status.textContent='Check-out must be after check-in.';form.elements.checkout?.focus();return;}let title='General Enquiry';if(form.dataset.form==='wedding'||f.type==='wedding')title='Weddings & Events';if(form.dataset.form==='stay'||f.type==='stay')title='Farmhouse Stay';if(form.dataset.form==='boutique'||f.type==='boutique')title='Boutique Shopping';const lines=[`Hello Ranawat Courtyard, I have a ${title.toLowerCase()} enquiry.`,`Name: ${f.name}`,`Phone: ${f.phone}`];if(f.email)lines.push(`Email: ${f.email}`);for(const [key,label] of [['eventType','Event type'],['date','Event date'],['guests','Expected guests'],['space','Space preference'],['checkin','Check-in'],['checkout','Check-out'],['collection','Collection'],['item','Item or style']])if(f[key])lines.push(`${label}: ${f[key]}`);if(f.notes)lines.push(`${form.dataset.form==='boutique'||f.type==='boutique'?'Item or style of interest':'Additional requirements'}: ${f.notes}`);lines.push('I understand this enquiry does not confirm a booking.');status.textContent='Opening WhatsApp with your enquiry details…';window.open(wa(lines.join('\n')),'_blank','noopener,noreferrer');}

document.addEventListener('click',e=>{const a=e.target.closest('a[href^="/"]');if(!a||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target==='_blank')return;const url=new URL(a.href,location.href);if(url.origin!==location.origin)return;e.preventDefault();history.pushState({},'',url.pathname+url.search+url.hash);render();});
window.addEventListener('popstate',render);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('body.menu-open')){$('.menu-toggle')?.click();}});
render();
